namespace mixxx {

AnalyzerBeatThis::AnalyzerBeatThis(Options options)
        : m_options(std::move(options)) {
}

bool AnalyzerBeatThis::initialize(audio::SampleRate sampleRate) {
    m_timings = {};
    m_diagnostics = {};
    m_beats.clear();
    m_downbeats.clear();
    m_frames = 0;
    m_failed = false;
    m_initialized = false;
    if (!m_audio.fileName().isEmpty()) {
        m_audio.remove();
    }
    m_sampleRate = sampleRate;
    const QString python = QStandardPaths::findExecutable(m_options.python);
    if (!sampleRate.isValid() || m_options.python.isEmpty() ||
            python.isEmpty() || !QFileInfo(m_options.script).isFile() ||
            !QFileInfo(m_options.checkpoint).isFile() ||
            m_options.sha256.size() != 64 || m_options.requestTimeoutMs <= 0 ||
            m_options.startupTimeoutMs <= 0) {
        qWarning() << "Beat This! requires a Python runtime, script, local "
                      "checkpoint and SHA-256";
        return false;
    }
    m_options.python = python;
    m_initialized = m_audio.open();
    return m_initialized;
}

bool AnalyzerBeatThis::processSamples(const CSAMPLE* input, SINT count) {
    if (!m_initialized || m_failed || !input || count < 0 || count % 2 != 0) {
        return false;
    }
    QElapsedTimer writeTimer;
    writeTimer.start();
    constexpr SINT kChunk = 4096;
    std::array<float, kChunk> mono;
    for (SINT offset = 0; offset < count / 2; offset += kChunk) {
        const SINT frames = std::min(kChunk, count / 2 - offset);
        for (SINT i = 0; i < frames; ++i) {
            mono[i] = input[(offset + i) * 2] * 0.5f +
                    input[(offset + i) * 2 + 1] * 0.5f;
            if (!std::isfinite(mono[i])) {
                m_failed = true;
                return false;
            }
        }
        const qint64 bytes = frames * static_cast<qint64>(sizeof(float));
        if (m_audio.write(reinterpret_cast<const char*>(mono.data()), bytes) !=
                bytes) {
            m_failed = true;
            return false;
        }
        m_frames += frames;
    }
    m_timings.insert("pcm_write",
            m_timings.value("pcm_write").toDouble() +
                    writeTimer.nsecsElapsed() / 1e6);
    return true;
}

bool AnalyzerBeatThis::finalize() {
    return finalizeWithProgress({});
}

bool AnalyzerBeatThis::finalizeWithProgress(
        const AnalyzerProgressCallback& progress) {
    if (!m_initialized || m_failed || m_frames == 0 || !m_audio.flush()) {
        return false;
    }
    m_initialized = false;
    const QString audioPath = m_audio.fileName();
    m_audio.close();
    m_diagnostics.insert("pcm_bytes", static_cast<double>(m_frames * sizeof(float)));
    m_diagnostics.insert("pcm_sample_rate", static_cast<int>(m_sampleRate.value()));
    if (m_options.persistent) {
        if (!s_session)
            s_session = std::make_unique<BeatThisSession>();
        QByteArray json;
        const bool completed = s_session->analyze(m_options,
                audioPath,
                m_sampleRate.value(),
                m_frames,
                progress,
                &json,
                &m_timings,
                &m_diagnostics);
        m_audio.remove();
        const bool parsed = completed &&
                parseResults(json,
                        m_options.sha256,
                        m_sampleRate,
                        m_frames,
                        &m_beats,
                        &m_downbeats);
        if (completed && !parsed)
            s_session->stop();
        return parsed;
    }
    QProcess process;
    process.setProgram(m_options.python);
    process.setArguments({m_options.script,
            "--timings",
            "--audio",
            audioPath,
            "--sample-rate",
            QString::number(m_sampleRate.value()),
            "--checkpoint",
            m_options.checkpoint,
            "--sha256",
            m_options.sha256});
    process.start();
    const bool started = process.waitForStarted(10000);
    QElapsedTimer timer;
    timer.start();
    QByteArray pendingError;
    QByteArray errorOutput;
    double lastProgress = 0;
    const auto consumeError = [&] {
        pendingError += process.readAllStandardError();
        int end = 0;
        while ((end = pendingError.indexOf('\n')) >= 0) {
            const auto line = pendingError.left(end).trimmed();
            pendingError.remove(0, end + 1);
            constexpr char kProgressPrefix[] = "MIXXX_BEAT_THIS_PROGRESS ";
            if (line.startsWith(kProgressPrefix)) {
                bool valid = false;
                const auto value =
                        line.mid(sizeof(kProgressPrefix) - 1).toDouble(&valid);
                if (valid && std::isfinite(value) && value >= lastProgress &&
                        value <= 1) {
                    lastProgress = value;
                    if (progress) {
                        progress(value);
                    }
                }
            } else {
                errorOutput.append(line).append('\n');
                errorOutput = errorOutput.right(4096);
            }
        }
        pendingError = pendingError.right(4096);
    };
    QByteArray standardOutput;
    bool outputTooLarge = false;
    const auto consumeOutput = [&] {
        standardOutput += process.read(kMaximumMessage - standardOutput.size() + 1);
        outputTooLarge = standardOutput.size() > kMaximumMessage;
    };
    while (started && process.state() != QProcess::NotRunning &&
            timer.elapsed() < m_options.requestTimeoutMs && !stopping() && !outputTooLarge) {
        process.waitForFinished(200);
        consumeError();
        consumeOutput();
    }
    consumeError();
    if (!outputTooLarge)
        consumeOutput();
    if (!started || process.state() != QProcess::NotRunning || outputTooLarge) {
        process.kill();
        process.waitForFinished(5000);
        m_audio.remove();
        qWarning() << "Beat This! process failed to start, was cancelled or "
                      "timed out";
        return false;
    }
    m_audio.remove();
    if (process.exitStatus() != QProcess::NormalExit ||
            process.exitCode() != 0) {
        errorOutput.append(pendingError);
        qWarning().noquote()
                << "Beat This!:" << QString::fromUtf8(errorOutput.right(4096));
        return false;
    }
    const auto output = std::move(standardOutput);
    const auto metadata = QJsonDocument::fromJson(output).object();
    workerTimings(metadata.value("timings").toObject(), &m_timings);
    m_timings.insert("worker_total", static_cast<double>(timer.elapsed()));
    if (metadata.value("peak_rss_bytes").isDouble()) {
        m_diagnostics.insert("worker_peak_rss_bytes", metadata.value("peak_rss_bytes"));
    }
    m_diagnostics.insert("worker_reused", false);
    m_diagnostics.insert("worker_rss_scope", "process_lifetime_high_water");
    const bool parsed = parseResults(output,
            m_options.sha256,
            m_sampleRate,
            m_frames,
            &m_beats,
            &m_downbeats);
    if (parsed) {
        qDebug() << "Beat This! analyzed" << m_frames / m_sampleRate.value()
                 << "seconds in" << timer.elapsed() << "ms;" << m_beats.size()
                 << "beats," << m_downbeats.size() << "downbeats";
    } else {
        qWarning() << "Beat This! returned invalid beat results";
    }
    return parsed;
}

void AnalyzerBeatThis::shutdownWorkerForCurrentThread() {
    s_session.reset();
}

bool AnalyzerBeatThis::parseResults(const QByteArray& json,
        const QString& sha256,
        audio::SampleRate sampleRate,
        SINT frames,
        QVector<audio::FramePos>* beats,
        QVector<audio::FramePos>* downbeats) {
    if (!sampleRate.isValid() || frames <= 0 || json.size() > 8 * 1024 * 1024) {
        return false;
    }
    const auto document = QJsonDocument::fromJson(json);
    const auto object = document.object();
    if (!document.isObject() || object.value("version").toInt() != 1 ||
            object.value("model_sha256").toString() != sha256.toLower()) {
        return false;
    }
    auto parse = [&](const QJsonValue& value,
                         QVector<audio::FramePos>* positions) {
        if (!value.isArray()) {
            return false;
        }
        for (const auto& entry : value.toArray()) {
            const double seconds = entry.toDouble(-1);
            const audio::FramePos rawPosition(seconds * sampleRate);
            const auto position = rawPosition.isValid()
                    ? rawPosition.toNearestFrameBoundary()
                    : rawPosition;
            if (!entry.isDouble() || !std::isfinite(seconds) || seconds < 0 ||
                    position.value() >= frames ||
                    (!positions->isEmpty() && position <= positions->back())) {
                return false;
            }
            positions->push_back(position);
        }
        return true;
    };
    QVector<audio::FramePos> parsedBeats;
    QVector<audio::FramePos> parsedDownbeats;
    if (!parse(object.value("beats"), &parsedBeats) || parsedBeats.size() < 2 ||
            !parse(object.value("downbeats"), &parsedDownbeats)) {
        return false;
    }
    for (const auto downbeat : parsedDownbeats) {
        if (!std::binary_search(
                    parsedBeats.begin(), parsedBeats.end(), downbeat)) {
            return false;
        }
    }
    *beats = std::move(parsedBeats);
    *downbeats = std::move(parsedDownbeats);
    return true;
}

} // namespace mixxx
